pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor address and two deposits (firstDeposit may be >0 to create existing balance,
    // secondDeposit is the fuzzed call that should be accumulated).
    function testFuzz_property(address actor, uint256 firstDeposit, uint256 secondDeposit) public {
        // keep actor non-zero to be a valid address
        vm.assume(actor != address(0));
        // bound amounts to reasonable range to avoid overflow of test harness sums (but keep wide)
        firstDeposit = bound(firstDeposit, 0, type(uint128).max);
        secondDeposit = bound(secondDeposit, 0, type(uint128).max);

        // Provide funds to actor so they can send value
        vm.deal(actor, firstDeposit + secondDeposit);

        // If firstDeposit > 0, make an initial deposit to establish a nonzero existing balance
        if (firstDeposit > 0) {
            vm.prank(actor);
            c.addToBalance{value: firstDeposit}();
        }

        // Record old balance via public getter
        uint256 oldBalance = c.getBalance(actor);

        // Perform the fuzzed second deposit
        vm.prank(actor);
        c.addToBalance{value: secondDeposit}();

        // Exactly one assertion: the reference contract always satisfies that the new balance equals old + msg.value
        uint256 newBalance = c.getBalance(actor);
        assertTrue(newBalance == oldBalance + secondDeposit);
    }
}

