pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// This test checks the universal property: for any caller `who` and any deposit `amt`, a successful
// addToBalance call increases the reported balance of `who` by `amt` on the reference contract.
// The mutant that never resets the reentrancy lock can cause a later deposit to revert and thus
// violate that property for some fuzzed inputs. We fuzz `who` and `amt`.
contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address who, uint256 amt) public {
        // keep domain wide but ensure amt is within payable range and non-negative
        // bound to a reasonable upper so vm.deal won't overflow wallets in the test env
        amt = bound(amt, 0, 1 ether);

        // Ensure 'who' is a non-zero address (EOA) that the fuzzer can drive
        // Allow zero address too; deposits from address(0) are fine in this context, so no assume

        // Fund the address so it can send `amt` wei
        vm.deal(who, amt);

        // record previous balance reported by contract for `who`
        uint256 before = c.getBalance(who);

        // perform the deposit as `who`
        vm.prank(who);
        // perform a low-level call to capture whether it reverts or not
        bool ok;
        try c.addToBalance{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call: if it succeeded, the reference implementation should always report balance increased by amt
        // The mutant that keeps locked_ true may cause the call to revert (ok == false) for some sequences.
        // We assert the universal property: whenever the deposit call returns successfully (ok == true),
        // then the contract's reported balance increased by exactly amt.
        uint256 after = c.getBalance(who);
        assertTrue(!ok || after == before + amt);
    }
}

