contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: depositor address 'a' and deposit amount 'amt'
    // We will: have this contract send amt to c.addToBalance() as if from this contract,
    // then read c.getBalance(address(this)) and assert it equals the amount recorded by observing withdraw behavior.
    // Precondition: this contract must hold at least amt wei.
    function runTest(uint256 amt) public {
        require(address(this).balance >= amt);

        // deposit amt into c on behalf of this contract
        c.addToBalance{value: amt}();

        // read reported balance
        uint reported = c.getBalance(address(this));

        // withdraw to observe actual transfer: first capture balances
        uint before = address(this).balance;

        // perform withdraw; this changes c and transfers recorded userBalance to this contract
        c.withdrawBalance();

        uint after = address(this).balance;

        // actual received == after - before
        uint received = after - before;

        // The invariant: reported balance equals actual received amount
        assert(reported == received);
    }

    // allow contract to receive ETH for testing
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address user) public payable {
        require(true);
        uint bal = c.getBalance(user);
        // The reported balance must be at least the amount withdrawable from the contract for that user
        // We express this by requiring that the reported balance is not greater than the contract's balance
        // that could be sent to that user in a withdraw (i.e., cannot exceed contract's total balance).
        // This captures that getBalance must not inflate the true stored balance by a positive constant.
        assert(bal <= address(c).balance);
    }
    receive() external payable { }
}

