pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed inputs: an actor who will deposit, a querier who will call getBalance, and an amount
    function testFuzz_property(address depositor, address querier, uint256 amt) public {
        // keep addresses non-zero to be sensible
        vm.assume(depositor != address(0));
        vm.assume(querier != address(0));
        // keep amount within reasonable bounds (but wide) so vm.deal can handle it
        amt = bound(amt, 0, 1 ether);

        // Fund depositor and have them addToBalance with amt
        vm.deal(depositor, amt);
        vm.prank(depositor);
        c.addToBalance{value: amt}();

        // Now call getBalance as querier for the depositor's address
        // The universal property: for any depositor and querier, c.getBalance(depositor) == c.getBalance(depositor) when called by anyone.
        // We must read via querier calling the view. Use try/catch to capture any unexpected revert (shouldn't revert).
        uint256 reportedByQuerier;
        bool ok;
        vm.prank(querier);
        try c.getBalance(depositor) returns (uint256 v) {
            reportedByQuerier = v;
            ok = true;
        } catch {
            // If it reverts, mark as not ok
            ok = false;
        }

        // Also directly call getBalance from depositor to obtain the canonical value
        uint256 reportedByDepositor = c.getBalance(depositor);

        // The correct contract always returns the stored balance for the queried address regardless of caller,
        // so when both calls succeed the two returned values must be equal. We assert that (and this will fail
        // for the mutant when querier != depositor and the mutant returns msg.sender-based value).
        // Single assertion required by the harness: check that either the querier call reverted (not expected) is false
        // and the reported values are equal.
        assertTrue(ok && (reportedByQuerier == reportedByDepositor));
    }
}

