import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: two distinct addresses and two deposit amounts.
    // General rule: For any caller A and any address U, c.getBalance(U) returns the stored balance for U.
    // We drive two accounts to deposit differing amounts and then query getBalance(U) from a different caller A.
    // The correct contract returns userBalance[U] regardless of caller; the mutant that uses msg.sender breaks this
    // whenever caller != U and balances differ. The test asserts that getBalance(U) equals the amount previously
    // deposited into U (the universal property). The mutant will fail for some fuzzed inputs where the two
    // addresses differ and deposits differ.
    function testFuzz_property(address depositor, address querier, uint256 amountDepositor, uint256 amountQuerier) public {
        // Keep domain wide but avoid zero addresses which may be undesirable in some environments
        vm.assume(depositor != address(0));
        vm.assume(querier != address(0));

        // Ensure amounts are reasonable and paid from fuzzed accounts
        amountDepositor = bound(amountDepositor, 0, 1 ether);
        amountQuerier = bound(amountQuerier, 0, 1 ether);

        // Fund depositor and querier so they can send value
        vm.deal(depositor, amountDepositor + 1 wei);
        vm.deal(querier, amountQuerier + 1 wei);

        // depositor makes a deposit to its balance
        if (amountDepositor > 0) {
            vm.prank(depositor);
            c.addToBalance{value: amountDepositor}();
        }

        // querier may also deposit to its own balance (we allow it; not necessary)
        if (amountQuerier > 0) {
            vm.prank(querier);
            c.addToBalance{value: amountQuerier}();
        }

        // Now, from the querier (caller), call getBalance on the depositor's address.
        // Universal property: for any inputs, c.getBalance(depositor) must equal the amount depositor deposited.
        uint256 reported;
        vm.prank(querier);
        reported = c.getBalance(depositor);

        // Exactly one assertion: the reference contract satisfies this for all inputs; the mutant breaks it
        // whenever querier != depositor and their balances differ.
        assertTrue(reported == amountDepositor);
    }
}

