contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: actor (who will deposit) and queried address u
    function testFuzz_property(address depositor, address u) public {
        // keep addresses wide-open but avoid the zero-address for clearer semantics
        vm.assume(depositor != address(0));
        vm.assume(u != address(0));

        // give depositor some ether and have them add to their balance
        uint256 deposit = 1 ether;
        vm.deal(depositor, deposit);
        vm.prank(depositor);
        c.addToBalance{value: deposit}();

        // Now read balances via the public view
        // The universal property: for any depositor and any queried address u,
        // the reference returns userBalance[u], independent of msg.sender.
        // We call getBalance as an external caller (fuzzer-supplied caller) to exercise msg.sender influence.
        bool ok;
        try c.getBalance(u) returns (uint256 val) {
            // call succeeded
            ok = true;
            // Verify that the returned value equals the stored mapping at key u by reading via a call from the depositor
            // We perform a second call as the original depositor and compare results; both calls must be equal in the correct contract.
            uint256 valFromDepositor = c.getBalance(u);
            // Single assertion: in the correct contract both callers observe the same value for getBalance(u)
            // If mutant changes getBalance to depend on msg.sender, this assertion will fail for some inputs.
            assertTrue(val == valFromDepositor);
        } catch {
            // If getBalance reverts (should not in correct contract), mark as failure
            ok = false;
            // The correct contract never reverts for this view; assertTrue on ok will fail if mutant changes revert behaviour
            assertTrue(ok);
        }
    }
